const language=document.querySelector('#language');let active=localStorage.getItem('suny-home-language')||'en';if(!SUNY_COPY[active])active='en';
function applyCopy(){const copy=SUNY_COPY[active];document.documentElement.lang=active==='zh'?'zh-CN':active;document.querySelectorAll('[data-i18n]').forEach(el=>{const value=copy[el.dataset.i18n];if(value!==undefined)el.innerHTML=value;});language.value=active;document.title=active==='en'?'SUNY | Professional Loudspeaker Drivers Since 1994':`SUNY | ${copy.hero_title.replace('<br>',' ')}`;}
language.addEventListener('change',()=>{active=language.value;localStorage.setItem('suny-home-language',active);applyCopy();});applyCopy();
